import { describe, expect, it } from "vitest";
import { packRangeFrameHistory, packRangeHistory, parseFftRange } from "../src/protocol";
import {
  decodeRangeFrame,
  decodeRangeHistory,
  encodeRangeFrame,
  encodeRangeHistory,
} from "../src/range";

// Generated by serverrs/src/codec/range.rs for 256 bins of
// -100 + 20*sin(i*0.1), minDb=-130, maxDb=0.
const FIXTURE =
  "107eff0000000100000020405c226a239d31ea95e25068027d8b60f2ad3a14a8eb99e5be1e6861c4b09e0b833e6ac3b49888c1a019f1da626a18d71c2a6587f216633a641a5a15f79e7babe80486bdf13383e6c7c8f8d5caa8b94d1458eb39218648e5ee089ad24555073e";

const CODES =
  "";

// Generated by range.rs::encode_history for 4 frames x 256 bins of
// (i * 13 + 7) % 256.
const HIST_PAYLOAD =
  "000383b210a950a587f8cfff8130e3668f8ad16b7ddde3200e830c24148ebaafa611e8fec78c4be2ab1841b763c025cfdd05648c1cfd445859e7bcb9b112";

const HIST_CODES =
  "";

function fromHex(hex: string): Uint8Array {
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = Number.parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }
  return out;
}

function toHex(bytes: Uint8Array): string {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
}

describe("range-coded FFT frames", () => {
  it("parses the 0x10 header", () => {
    const frame = fromHex(FIXTURE);
    const parsed = parseFftRange(new Uint8Array(frame).buffer as ArrayBuffer);
    expect(parsed.bins).toBe(256);
    expect(parsed.minDb).toBe(-130);
    expect(parsed.maxDb).toBe(0);
    expect(parsed.payload.length).toBe(frame.length - 9);
  });

  it("decodes the same codes as the Rust decoder", () => {
    const frame = fromHex(FIXTURE);
    const parsed = parseFftRange(new Uint8Array(frame).buffer as ArrayBuffer);
    const decoded = decodeRangeFrame(parsed.payload, parsed.bins);
    expect(toHex(decoded)).toBe(CODES);
  });
});

describe("range-coded history", () => {
  it("encodes the same bytes as the Rust encoder", () => {
    const frames = [0, 1, 2, 3].map((f) => {
      const frame = new Uint8Array(256);
      for (let i = 0; i < 256; i++) frame[i] = ((f * 256 + i) * 13 + 7) % 256;
      return frame;
    });
    expect(toHex(encodeRangeHistory(frames, 256))).toBe(HIST_PAYLOAD);
  });

  it("decodes the Rust history fixture", () => {
    const decoded = decodeRangeHistory(fromHex(HIST_PAYLOAD), 4, 256);
    expect(toHex(decoded)).toBe(HIST_CODES);
  });

  it("packs a codec-3 history message", () => {
    const frames = [new Uint8Array([1, 2]), new Uint8Array([3, 4])];
    const buf = packRangeHistory(frames, 2, -130, 0);
    const view = new DataView(buf);
    expect(view.getUint8(0)).toBe(0x0d);
    expect(view.getUint16(1, true)).toBe(2);
    expect(view.getUint32(3, true)).toBe(2);
    expect(view.getUint8(11)).toBe(3);
  });

  it("packs per-frame range history and round-trips", () => {
    const frames = [
      new Uint8Array([10, 20, 30, 40]),
      new Uint8Array([11, 21, 31, 41]),
    ];
    const payloads = frames.map((f) => encodeRangeFrame(f));
    const buf = packRangeFrameHistory(payloads, 4, -130, 0);
    const view = new DataView(buf);
    expect(view.getUint8(0)).toBe(0x0d);
    expect(view.getUint16(1, true)).toBe(2);
    expect(view.getUint32(3, true)).toBe(4);
    expect(view.getUint8(11)).toBe(4);

    let pos = 12;
    for (let i = 0; i < frames.length; i++) {
      const len = view.getUint32(pos, true);
      pos += 4;
      const decoded = decodeRangeHistory(
        new Uint8Array(buf, pos, len),
        1,
        4,
      );
      expect(Array.from(decoded)).toEqual(Array.from(frames[i]));
      pos += len;
    }
  });
});

